//! Integration tests for the PCAP / PCAPNG analysis pipeline.
//!
//! Fixtures are generated by scripts/gen_pcap_fixtures.cjs so every byte, timestamp
//! and expected decoded value below is known exactly.

use nullplinth_lib::db::Db;
use nullplinth_lib::pcap;
use nullplinth_lib::types::{PacketQuery, PacketRow};
use rusqlite::Connection;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};

static DB_COUNTER: AtomicUsize = AtomicUsize::new(0);

struct TestDb {
    db: Db,
    path: PathBuf,
}

impl TestDb {
    fn new(label: &str) -> TestDb {
        let n = DB_COUNTER.fetch_add(1, Ordering::SeqCst);
        let mut path = std::env::temp_dir();
        path.push(format!(
            "nullplinth_pcap_{label}_{}_{}_{n}.db",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0)
        ));
        let db = Db::open(path.clone()).expect("open temp database");
        TestDb { db, path }
    }

    fn conn(&self) -> Connection {
        self.db.conn().expect("open sqlite connection")
    }
}

impl Drop for TestDb {
    fn drop(&mut self) {
        for suffix in ["", "-wal", "-shm"] {
            let _ = std::fs::remove_file(format!("{}{suffix}", self.path.display()));
        }
    }
}

fn fixture(name: &str) -> String {
    let root: &Path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("crate dir has a parent");
    root.join("fixtures")
        .join("pcap")
        .join(name)
        .to_string_lossy()
        .to_string()
}

fn all_packets(conn: &Connection, capture_id: i64) -> Vec<PacketRow> {
    let query = PacketQuery {
        capture_id: Some(capture_id),
        filters: vec![],
        from_ts: None,
        to_ts: None,
        sort: "packetNo".to_string(),
        sort_dir: "asc".to_string(),
        page: 0,
        page_size: 200,
    };
    pcap::search_packets(conn, &query).expect("search packets").packets
}

fn find_packet(conn: &Connection, capture_id: i64, protocol: &str) -> PacketRow {
    all_packets(conn, capture_id)
        .into_iter()
        .find(|p| p.protocol.as_deref() == Some(protocol))
        .unwrap_or_else(|| panic!("no {protocol} packet in capture"))
}

fn hex_bytes(hex: &str) -> Vec<&str> {
    hex.split_whitespace().collect()
}

// ------------------------------------------------------------------- pcap

#[test]
fn pcap_imports_and_decodes_every_packet() {
    let t = TestDb::new("basic_pcap");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("basic.pcap")).expect("import basic.pcap");

    assert_eq!(capture.packet_count, 7, "fixture has 7 packets");
    assert_eq!(capture.file_name.as_deref(), Some("basic.pcap"));
    assert!(capture.file_size.unwrap_or(0) > 0);
    assert!(capture
        .link_type
        .as_deref()
        .unwrap_or("")
        .contains("Ethernet"));
    let hash = capture.file_hash.as_deref().expect("sha256 file hash");
    assert_eq!(hash.len(), 64, "sha256 hex length");

    let rows = all_packets(&conn, capture.id);
    assert_eq!(rows.len(), 7);
    assert_eq!(rows[0].ts, 1_700_000_000_000, "epoch ms from pcap header");

    // 1: TCP SYN
    assert_eq!(rows[0].src_ip.as_deref(), Some("10.0.0.5"));
    assert_eq!(rows[0].dst_ip.as_deref(), Some("93.184.216.34"));
    assert_eq!(rows[0].src_port, Some(54321));
    assert_eq!(rows[0].dst_port, Some(80));
    assert_eq!(rows[0].protocol.as_deref(), Some("TCP"));
    assert_eq!(rows[0].transport.as_deref(), Some("TCP"));
    assert_eq!(rows[0].tcp_flags.as_deref(), Some("SYN"));
    assert_eq!(rows[0].caplen, 54);
    assert_eq!(rows[0].origlen, 54);

    // 2: TCP SYN, ACK
    assert_eq!(rows[1].tcp_flags.as_deref(), Some("SYN, ACK"));
    assert_eq!(rows[1].src_ip.as_deref(), Some("93.184.216.34"));
    assert_eq!(rows[1].ts, 1_700_000_000_001);

    // 3: DNS query
    assert_eq!(rows[2].protocol.as_deref(), Some("DNS"));
    assert_eq!(rows[2].src_port, Some(55000));
    assert_eq!(rows[2].dst_port, Some(53));
    let summary = rows[2].summary.as_deref().unwrap_or("");
    assert!(summary.contains("DNS query A example.com"), "summary was {summary}");

    // 4: DNS response with an A record
    assert_eq!(rows[3].protocol.as_deref(), Some("DNS"));
    assert_eq!(rows[3].src_ip.as_deref(), Some("8.8.8.8"));
    let summary = rows[3].summary.as_deref().unwrap_or("");
    assert!(summary.contains("DNS response"), "summary was {summary}");
    assert!(summary.contains("rcode=0 (NoError)"), "summary was {summary}");
    assert_eq!(rows[3].ts, 1_700_000_000_003);

    // 5: HTTP GET on port 80
    assert_eq!(rows[4].protocol.as_deref(), Some("HTTP"));
    assert_eq!(rows[4].payload_len, 93, "captured HTTP payload bytes");
    assert_eq!(rows[4].tcp_flags.as_deref(), Some("PSH, ACK"));
    let summary = rows[4].summary.as_deref().unwrap_or("");
    assert!(summary.contains("HTTP GET /index.html"), "summary was {summary}");
    assert!(summary.contains("Host: example.com"), "summary was {summary}");

    // 6: plain ACK
    assert_eq!(rows[5].tcp_flags.as_deref(), Some("ACK"));

    // 7: TLS ClientHello with SNI
    assert_eq!(rows[6].protocol.as_deref(), Some("TLS"));
    assert_eq!(rows[6].dst_port, Some(443));
    let summary = rows[6].summary.as_deref().unwrap_or("");
    assert!(summary.contains("ClientHello"), "summary was {summary}");
    assert!(summary.contains("SNI example.com"), "summary was {summary}");
}

#[test]
fn pcapng_imports_and_matches_pcap_decoding() {
    let t = TestDb::new("basic_pcapng");
    let conn = t.conn();
    let capture =
        pcap::import_core(&conn, &fixture("basic.pcapng")).expect("import basic.pcapng");
    assert_eq!(capture.packet_count, 7);
    assert!(capture.link_type.as_deref().unwrap_or("").contains("Ethernet"));

    let rows = all_packets(&conn, capture.id);
    assert_eq!(rows.len(), 7);
    assert_eq!(rows[0].ts, 1_700_000_000_000);
    assert_eq!(rows[0].src_ip.as_deref(), Some("10.0.0.5"));
    assert_eq!(rows[1].tcp_flags.as_deref(), Some("SYN, ACK"));
    assert_eq!(rows[2].protocol.as_deref(), Some("DNS"));
    assert!(rows[2]
        .summary
        .as_deref()
        .unwrap_or("")
        .contains("example.com"));
    assert_eq!(rows[4].protocol.as_deref(), Some("HTTP"));
    assert!(rows[4]
        .summary
        .as_deref()
        .unwrap_or("")
        .contains("Host: example.com"));
    assert_eq!(rows[6].protocol.as_deref(), Some("TLS"));
    // pcapng timestamps use the interface tsresol (microseconds) just like pcap here.
    assert_eq!(rows[6].ts, 1_700_000_000_006);
}

#[test]
fn get_packet_returns_layers_hex_and_ascii() {
    let t = TestDb::new("detail");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("basic.pcap")).expect("import");
    let http = find_packet(&conn, capture.id, "HTTP");
    let detail = pcap::get_packet(&conn, http.id).expect("packet detail");

    assert!(detail.unsupported.is_none());

    // Hex is byte pairs separated by spaces, one entry per captured byte.
    let bytes = hex_bytes(&detail.hex);
    assert_eq!(bytes.len(), http.caplen as usize);
    assert_eq!(
        &bytes[..14],
        &[
            "02", "00", "00", "00", "00", "77", // destination MAC
            "02", "00", "00", "00", "00", "05", // source MAC
            "08", "00" // ethertype IPv4
        ]
    );

    // ASCII dump: 16 bytes per line, non-printable as '.'
    let first_line = detail.ascii.lines().next().expect("ascii first line");
    assert_eq!(first_line.chars().count(), 16);
    let flat_ascii = detail.ascii.replace('\n', "");
    assert!(
        flat_ascii.contains("GET /index.html HTTP/1.1"),
        "ascii was {}",
        detail.ascii
    );
    assert!(flat_ascii.contains("Host: example.com"));
    assert!(flat_ascii.contains("User-Agent: nullplinth-test/1.0"));

    // Layer tree order and HTTP fields.
    let names: Vec<&str> = detail.layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names, vec!["eth", "ip", "tcp", "http"]);
    let http_layer = detail
        .layers
        .iter()
        .find(|l| l.name == "http")
        .expect("http layer");
    let field = |name: &str| {
        http_layer
            .fields
            .iter()
            .find(|f| f.name.eq_ignore_ascii_case(name))
            .map(|f| f.value.clone())
            .unwrap_or_else(|| panic!("missing HTTP field {name}"))
    };
    assert_eq!(field("Host"), "example.com");
    assert_eq!(field("Method"), "GET");
    assert_eq!(field("URI"), "/index.html");
    assert_eq!(field("User-Agent"), "nullplinth-test/1.0");

    // DNS layer carries the decoded question name, type and rcode.
    let dns = find_packet(&conn, capture.id, "DNS");
    let dns_detail = pcap::get_packet(&conn, dns.id).expect("dns detail");
    let dns_layer = dns_detail
        .layers
        .iter()
        .find(|l| l.name == "dns")
        .expect("dns layer");
    let has_field = |name: &str, value: &str| {
        dns_layer
            .fields
            .iter()
            .any(|f| f.name == name && f.value.contains(value))
    };
    assert!(has_field("Query Name", "example.com"));
    assert!(has_field("Query Type", "A (1)"));
    assert!(has_field("Rcode", "NoError"));

    // Ethernet/IP/TCP fields exist too.
    let ip_layer = dns_detail.layers.iter().find(|l| l.name == "ip").unwrap();
    assert!(ip_layer
        .fields
        .iter()
        .any(|f| f.name == "Source Address" && f.value == "10.0.0.5"));
    assert!(ip_layer
        .fields
        .iter()
        .any(|f| f.name == "Protocol" && f.value.contains("UDP")));
}

#[test]
fn flows_are_bidirectional_and_flow_packets_are_complete() {
    let t = TestDb::new("flows");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("basic.pcap")).expect("import");

    let flows = pcap::list_flows(&conn, Some(capture.id)).expect("list flows");
    assert_eq!(flows.len(), 3, "two TCP conversations and one UDP conversation");

    let http_flow = flows
        .iter()
        .find(|f| f.dst_port == Some(80) || f.src_port == Some(80))
        .expect("flow on port 80");
    assert_eq!(http_flow.transport, "tcp");
    assert_eq!(http_flow.packet_count, 4, "SYN, SYN-ACK, GET and ACK");
    assert_eq!(http_flow.bytes_total, 309, "sum of wire lengths");
    assert_eq!(http_flow.first_ts, 1_700_000_000_000);
    assert_eq!(http_flow.last_ts, 1_700_000_000_005);
    assert_eq!(http_flow.src_ip.as_deref(), Some("10.0.0.5"));
    assert_eq!(http_flow.src_port, Some(54321));
    assert_eq!(http_flow.dst_ip.as_deref(), Some("93.184.216.34"));
    assert_eq!(http_flow.dst_port, Some(80));

    let flow_packets = pcap::flow_packets(&conn, http_flow.id).expect("flow packets");
    assert_eq!(flow_packets.len(), 4);
    assert_eq!(flow_packets[0].tcp_flags.as_deref(), Some("SYN"));
    assert_eq!(flow_packets[3].tcp_flags.as_deref(), Some("ACK"));
    let mut directions: Vec<&str> = flow_packets
        .iter()
        .map(|p| p.src_ip.as_deref().unwrap_or(""))
        .collect();
    directions.sort_unstable();
    directions.dedup();
    assert_eq!(directions.len(), 2, "both directions in one flow");

    let dns_flow = flows
        .iter()
        .find(|f| f.transport == "udp")
        .expect("udp flow");
    assert_eq!(dns_flow.packet_count, 2);
    assert_eq!(dns_flow.bytes_total, 158);

    let tls_flow = flows
        .iter()
        .find(|f| f.dst_port == Some(443) || f.src_port == Some(443))
        .expect("tls flow");
    assert_eq!(tls_flow.packet_count, 1);

    // list_flows without a capture filter also works.
    assert_eq!(pcap::list_flows(&conn, None).expect("all flows").len(), 3);
}

#[test]
fn packet_search_filters_and_pagination() {
    let t = TestDb::new("search");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("basic.pcap")).expect("import");

    let run = |filters: Vec<(&str, &str, &str)>, from: Option<i64>, to: Option<i64>, page: u32, size: u32| {
        let query = PacketQuery {
            capture_id: Some(capture.id),
            filters: filters
                .into_iter()
                .map(|(field, op, value)| nullplinth_lib::types::FilterRow {
                    field: field.to_string(),
                    op: op.to_string(),
                    value: value.to_string(),
                })
                .collect(),
            from_ts: from,
            to_ts: to,
            sort: "packetNo".to_string(),
            sort_dir: "asc".to_string(),
            page,
            page_size: size,
        };
        pcap::search_packets(&conn, &query)
    };

    let protocol_dns = run(vec![("protocol", "eq", "dns")], None, None, 0, 50).expect("filter");
    assert_eq!(protocol_dns.total, 2);

    let dst_port_80 = run(vec![("dstPort", "eq", "80")], None, None, 0, 50).expect("filter");
    assert_eq!(dst_port_80.total, 2, "SYN and HTTP request go to port 80");

    let syn = run(vec![("tcpFlags", "contains", "SYN")], None, None, 0, 50).expect("filter");
    assert_eq!(syn.total, 2);

    let time_window = run(
        vec![],
        Some(1_700_000_000_002),
        Some(1_700_000_000_004),
        0,
        50,
    )
    .expect("filter");
    assert_eq!(time_window.total, 3);

    let long_packets = run(vec![("packetLength", "gt", "100")], None, None, 0, 50).expect("filter");
    assert_eq!(long_packets.total, 2, "HTTP GET and TLS ClientHello");

    let internal = run(vec![("srcIp", "inCidr", "10.0.0.0/8")], None, None, 0, 50).expect("filter");
    assert_eq!(internal.total, 4);

    let src_ip = run(
        vec![("srcIp", "eq", "8.8.8.8")],
        None,
        None,
        0,
        50,
    )
    .expect("filter");
    assert_eq!(src_ip.total, 1);

    let paged = run(vec![], None, None, 1, 2).expect("pagination");
    assert_eq!(paged.total, 7);
    assert_eq!(paged.packets.len(), 2);
    assert_eq!(paged.page, 1);
    assert_eq!(paged.page_size, 2);

    let bad_field = run(vec![("nonsense", "eq", "x")], None, None, 0, 50);
    assert!(bad_field.is_err(), "unknown filter field must be rejected");
    assert!(bad_field
        .unwrap_err()
        .to_string()
        .contains("unknown packet field"));

    let bad_ip = run(vec![("srcIp", "eq", "999.1.1.1")], None, None, 0, 50);
    assert!(bad_ip.is_err(), "invalid IP must be rejected");
    assert!(bad_ip.unwrap_err().to_string().contains("valid IP address"));
}

#[test]
fn truncated_packets_are_stored_without_panic() {
    let t = TestDb::new("truncated");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("truncated.pcap")).expect("import truncated");
    assert_eq!(capture.packet_count, 2);

    let rows = all_packets(&conn, capture.id);
    assert_eq!(rows.len(), 2);

    // Frame 1: TCP header cut off after 6 bytes.
    assert_eq!(rows[0].caplen, 40);
    assert_eq!(rows[0].origlen, 154);
    assert!(rows[0].caplen < rows[0].origlen);
    assert_eq!(rows[0].protocol.as_deref(), Some("TCP"));
    let detail = pcap::get_packet(&conn, rows[0].id).expect("detail of truncated header");
    assert_eq!(hex_bytes(&detail.hex).len(), 40);
    assert!(detail
        .layers
        .iter()
        .any(|l| l.name == "tcp" && l.fields.iter().any(|f| f.value.contains("truncated"))));

    // Frame 2: headers complete, payload truncated to 20 of 100 bytes.
    assert_eq!(rows[1].caplen, 74);
    assert_eq!(rows[1].payload_len, 20);
    let detail = pcap::get_packet(&conn, rows[1].id).expect("detail of truncated payload");
    assert_eq!(hex_bytes(&detail.hex).len(), 74);
    assert!(detail
        .layers
        .iter()
        .find(|l| l.name == "ip")
        .map(|l| l.fields.iter().any(|f| f.value.contains("truncated")))
        .unwrap_or(false));
}

#[test]
fn unsupported_link_type_keeps_raw_bytes_and_explains() {
    let t = TestDb::new("unsupported");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("unsupported_linktype.pcap"))
        .expect("import with unsupported link type must succeed");
    assert_eq!(capture.packet_count, 1);
    assert!(
        capture.link_type.as_deref().unwrap_or("").contains("113"),
        "link type was {:?}",
        capture.link_type
    );

    let rows = all_packets(&conn, capture.id);
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].protocol.as_deref(), Some("Unknown"));
    assert_eq!(rows[0].caplen, 24);

    let detail = pcap::get_packet(&conn, rows[0].id).expect("detail");
    let unsupported = detail.unsupported.expect("unsupported message");
    assert!(
        unsupported.contains("Unsupported link type"),
        "message was {unsupported}"
    );
    assert_eq!(hex_bytes(&detail.hex).len(), 24, "raw bytes preserved");
    assert_eq!(detail.layers.len(), 1);
    assert_eq!(detail.layers[0].name, "frame");
}

#[test]
fn malformed_file_returns_clear_error_and_leaves_no_capture() {
    let t = TestDb::new("malformed");
    let conn = t.conn();
    let result = pcap::import_core(&conn, &fixture("malformed.pcap"));
    assert!(result.is_err(), "garbage file must not import");
    let message = result.unwrap_err().to_string();
    assert!(
        message.contains("not a PCAP or PCAPNG") || message.contains("could not be parsed"),
        "unexpected error: {message}"
    );
    assert!(
        pcap::list_captures(&conn).expect("list").is_empty(),
        "a failed import must not leave a capture row"
    );

    let missing = pcap::import_core(&conn, &fixture("does-not-exist.pcap"));
    assert!(missing.is_err());
    assert!(missing
        .unwrap_err()
        .to_string()
        .contains("cannot read capture file"));
}

#[test]
fn duplicate_import_returns_existing_capture() {
    let t = TestDb::new("duplicate");
    let conn = t.conn();
    let first = pcap::import_core(&conn, &fixture("basic.pcap")).expect("first import");
    let second = pcap::import_core(&conn, &fixture("basic.pcap")).expect("second import");
    assert_eq!(first.id, second.id, "same file hash must not import twice");
    assert_eq!(first.file_hash, second.file_hash);
    assert_eq!(pcap::list_captures(&conn).expect("list").len(), 1);
    assert_eq!(all_packets(&conn, second.id).len(), 7);
}

#[test]
fn vlan_ipv6_and_icmp_decode() {
    let t = TestDb::new("vlan");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("vlan_ipv6.pcap")).expect("import vlan fixture");
    assert_eq!(capture.packet_count, 3);

    let rows = all_packets(&conn, capture.id);

    // VLAN tagged IPv4/UDP
    assert_eq!(rows[0].protocol.as_deref(), Some("UDP"));
    assert_eq!(rows[0].src_ip.as_deref(), Some("10.0.0.5"));
    assert_eq!(rows[0].dst_ip.as_deref(), Some("10.0.0.99"));
    assert_eq!(rows[0].dst_port, Some(5353));
    let detail = pcap::get_packet(&conn, rows[0].id).expect("detail");
    let vlan = detail
        .layers
        .iter()
        .find(|l| l.name == "vlan")
        .expect("vlan layer");
    assert!(vlan
        .fields
        .iter()
        .any(|f| f.name == "VLAN ID" && f.value == "100"));

    // IPv6 / TCP
    assert_eq!(rows[1].protocol.as_deref(), Some("TCP"));
    assert_eq!(rows[1].src_ip.as_deref(), Some("2001:db8::1"));
    assert_eq!(rows[1].dst_ip.as_deref(), Some("2001:db8::2"));
    assert_eq!(rows[1].dst_port, Some(443));
    assert_eq!(rows[1].tcp_flags.as_deref(), Some("SYN"));

    // ICMP echo request
    assert_eq!(rows[2].protocol.as_deref(), Some("ICMP"));
    assert!(rows[2]
        .summary
        .as_deref()
        .unwrap_or("")
        .contains("Echo Request"));

    let flows = pcap::list_flows(&conn, Some(capture.id)).expect("flows");
    assert_eq!(flows.len(), 3, "udp, ipv6 tcp and icmp conversations");
}

#[test]
fn delete_capture_removes_packets_and_flows() {
    let t = TestDb::new("delete");
    let conn = t.conn();
    let capture = pcap::import_core(&conn, &fixture("basic.pcap")).expect("import");
    pcap::delete_capture(&conn, capture.id).expect("delete");
    assert!(pcap::list_captures(&conn).expect("list").is_empty());
    assert_eq!(all_packets(&conn, capture.id).len(), 0);
    assert!(pcap::list_flows(&conn, None).expect("flows").is_empty());
    assert!(pcap::get_capture(&conn, capture.id).is_err());
}

#[test]
fn import_progress_reports_final_count() {
    let t = TestDb::new("progress");
    let conn = t.conn();
    let mut seen: Vec<(i64, Option<i64>)> = Vec::new();
    let capture = pcap::import_with_progress(&conn, &fixture("basic.pcap"), |processed, total| {
        seen.push((processed, total));
    })
    .expect("import with progress");
    assert_eq!(capture.packet_count, 7);
    assert!(!seen.is_empty());
    assert_eq!(seen.last().copied(), Some((7, Some(7))));
}
